from itertools import product

def find_sequence(length, max_autocorrelation):
    for seq in product([-1, 1], repeat=length):
        autocorrelation = sum(sum(seq[i] * seq[i + k] for i in range(length - k)) ** 2 for k in range(1, length))
        if autocorrelation <= max_autocorrelation:
            return list(seq)
    return "UNSATISFIABLE"

print(find_sequence(22, 56))
